+func (m MockRows) Close() error               { return nil }
+func (m MockRows) Next() bool                 { return false }
+func (m MockRows) Scan(...interface{}) error  { return nil }
+
+type NestedStruct struct {
+	ID   int    `ksql:"id"`
+	Name string `ksql:"name"`
+}
+
+type MainStruct struct {
+	Nested *NestedStruct `tablename:"nested"`
+}
+
+func getScanArgsForNestedStructs(
+	ctx context.Context,
+	dialect sqldialect.Provider,
+	rows MockRows,
+	t reflect.Type,
+	v reflect.Value,
+	info structs.StructInfo,
+) (attrNames []string, scanArgs []interface{}, _ error) {
+	for i := 0; i < v.NumField(); i++ {
+		if !info.ByIndex(i).Valid {
+			continue
+		}
+
+		// Handle case where type is pointer
+		fieldType := t.Field(i).Type
+		if fieldType.Kind() == reflect.Ptr {
+			fieldType = fieldType.Elem()
+		}
+		nestedStructInfo, err := structs.GetTagInfo(fieldType)
+		if err != nil {
+			return nil, nil, err
+		}
+
+		nestedStructValue := v.Field(i)
+		// Handle case where value is a nil pointer
+		if t.Field(i).Type.Kind() == reflect.Ptr {
+			if nestedStructValue.IsNil() {
+				// Initialize the pointer to a zero value struct
+				nestedStructValue.Set(reflect.New(nestedStructValue.Type().Elem()))
+			}
+			nestedStructValue = nestedStructValue.Elem()
+		}
+		for j := 0; j < nestedStructValue.NumField(); j++ {
+			fieldInfo := nestedStructInfo.ByIndex(j)
+			if !fieldInfo.Valid {
+				continue
+			}
+
+			valueScanner := nestedStructValue.Field(fieldInfo.Index).Addr().Interface()
+			// Simplified version without modifiers for testing
+			scanArgs = append(scanArgs, valueScanner)
+			attrNames = append(attrNames, info.ByIndex(i).AttrName+"."+fieldInfo.AttrName)
+		}
+	}
+
+	return attrNames, scanArgs, nil
+}
